final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Cedar-based access control for a bookstore application using Amazon Verified Permissions.
  Creates a policy store with STRICT schema validation for the Bookstore namespace (Role, User,
  and Book entities plus the View and ViewWithPremiumOffers actions that require a request-context
  region), defines the static Cedar policies (admin access, named-admin forbid, publisher
  owner-scoped access, named user-to-book grant, customer membership-duration permit/forbid, and
  region-based forbids), and publishes the policy store ID to AWS Systems Manager Parameter Store.

Parameters:
  NamePrefix:
    Type: String
    Default: bookstore
    MinLength: 2
    MaxLength: 20
    AllowedPattern: '^[a-z0-9][a-z0-9-]*$'
    ConstraintDescription: Lowercase alphanumeric characters and hyphens, 2-20 characters, starting with a letter or a digit.
    Description: Prefix used to build the deterministic name of the SSM parameter that publishes the policy store ID.

Resources:

  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {},
                "User": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "memberOfRole": {
                        "type": "Entity",
                        "name": "Role",
                        "required": false
                      },
                      "yearsAsMember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User",
                        "required": true
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  AdminViewAnyBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit any user in the Admin role to view any book.
          Statement: |
            permit (
                principal,
                action == Bookstore::Action::"View",
                resource
            ) when {
                principal.memberOfRole == Bookstore::Role::"Admin"
            };

  ForbidNamedAdminViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Explicitly forbid the named administrator from viewing any book, overriding the general Admin permit.
          Statement: |
            forbid (
                principal == Bookstore::User::"admin",
                action == Bookstore::Action::"View",
                resource
            );

  PublisherViewOwnedBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit a user in the Publisher role to view only the books that user owns.
          Statement: |
            permit (
                principal,
                action == Bookstore::Action::"View",
                resource
            ) when {
                principal.memberOfRole == Bookstore::Role::"Publisher" &&
                resource.owner == principal
            };

  NamedUserViewNamedBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit one specific named user to view one specific named book.
          Statement: |
            permit (
                principal == Bookstore::User::"alice",
                action == Bookstore::Action::"View",
                resource == Bookstore::Book::"book-0001"
            );

  CustomerPremiumOffersTenurePermitPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit a user in the Customer role to view premium offers only after two or more years of membership.
          Statement: |
            permit (
                principal,
                action == Bookstore::Action::"ViewWithPremiumOffers",
                resource
            ) when {
                principal.memberOfRole == Bookstore::Role::"Customer" &&
                principal.yearsAsMember >= 2
            };

  CustomerPremiumOffersTenureForbidPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid a user in the Customer role with less than two years of membership from viewing premium offers.
          Statement: |
            forbid (
                principal,
                action == Bookstore::Action::"ViewWithPremiumOffers",
                resource
            ) when {
                principal.memberOfRole == Bookstore::Role::"Customer" &&
                principal.yearsAsMember < 2
            };

  RegionRestrictViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid the View action for all principals and resources whenever the request context region is not the United States.
          Statement: |
            forbid (
                principal,
                action == Bookstore::Action::"View",
                resource
            ) when {
                context.region != "US"
            };

  RegionRestrictViewWithPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid the ViewWithPremiumOffers action for all principals and resources whenever the request context region is not the United States.
          Statement: |
            forbid (
                principal,
                action == Bookstore::Action::"ViewWithPremiumOffers",
                resource
            ) when {
                context.region != "US"
            };

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      Name: !Sub '/${NamePrefix}/verified-permissions/bookstore-policy-store-id'
      Type: String
      Value: !Ref BookstorePolicyStore
      Description: Identifier of the Amazon Verified Permissions policy store that stores the bookstore Cedar schema and policies.
      Tags:
        Name: !Sub '${NamePrefix}-bookstore-policy-store-id'

Outputs:
  PolicyStoreId:
    Description: ID of the Amazon Verified Permissions policy store for the bookstore application.
    Value: !Ref BookstorePolicyStore
  PolicyStoreArn:
    Description: ARN of the Amazon Verified Permissions policy store for the bookstore application.
    Value: !GetAtt BookstorePolicyStore.Arn
  PolicyStoreIdParameterName:
    Description: Name of the SSM parameter that publishes the policy store ID.
    Value: !Ref PolicyStoreIdParameter
  PolicyStoreIdParameterArn:
    Description: ARN of the SSM parameter that publishes the policy store ID.
    Value: !Sub 'arn:${AWS::Partition}:ssm:${AWS::Region}:${AWS::AccountId}:parameter${PolicyStoreIdParameter}'

AWSTemplateFormatVersion: '2010-09-09'
Description: SimpleTodoAPI - AWS AppSync GraphQL API backed by DynamoDB, using JavaScript (APPSYNC_JS) resolvers.

Resources:

  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      TableName: SimpleTodoTable
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL

  AppSyncTodoServiceRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: SimpleTodoAPI-AppSync-DynamoDB-Role
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncTodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  SimpleTodoAPI:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY
      XrayEnabled: true

  SimpleTodoAPISchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Definition: |
        type Todo {
          id: ID!
          title: String!
          description: String
          status: String
          owner: String
        }

        input CreateTodoInput {
          id: ID
          title: String!
          description: String
          status: String
          owner: String
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          status: String
          owner: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]
          todosByOwner(owner: String!, limit: Int, nextToken: String): [Todo]
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        schema {
          query: Query
          mutation: Mutation
        }

  SimpleTodoAPIApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Description: SimpleTodoAPI default API key
      Expires: 1767225600

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Name: TodoTableDataSource
      Type: AMAZON_DYNAMODB
      Description: DynamoDB data source for SimpleTodoTable
      ServiceRoleArn: !GetAtt AppSyncTodoServiceRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: SimpleTodoAPISchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const id = input.id || util.autoId();
          const item = {
            id,
            title: input.title,
            description: input.description,
            status: input.status,
            owner: input.owner,
          };
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: SimpleTodoAPISchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const fields = ['title', 'description', 'status', 'owner'];
          const sets = [];
          const expressionNames = {};
          const expressionValues = {};

          for (const field of fields) {
            if (input[field] !== undefined && input[field] !== null) {
              sets.push(`#${field} = :${field}`);
              expressionNames[`#${field}`] = field;
              expressionValues[`:${field}`] = input[field];
            }
          }

          if (sets.length === 0) {
            util.error('No updatable fields were provided.', 'BadRequest');
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: 'SET ' + sets.join(', '),
              expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: SimpleTodoAPISchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: SimpleTodoAPISchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: SimpleTodoAPISchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {
            operation: 'Scan',
          };
        }

        export function response(ctx) {
          return ctx.result.items;
        }

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: SimpleTodoAPISchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: todosByOwner
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { owner, limit, nextToken } = ctx.args;
          return {
            operation: 'Query',
            index: 'owner-index',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': owner }),
            },
            limit: limit,
            nextToken: nextToken,
          };
        }

        export function response(ctx) {
          return ctx.result.items;
        }

Outputs:

  GraphQLApiId:
    Description: The ID of the SimpleTodoAPI GraphQL API
    Value: !GetAtt SimpleTodoAPI.ApiId

  GraphQLApiUrl:
    Description: The URL of the SimpleTodoAPI GraphQL API
    Value: !GetAtt SimpleTodoAPI.GraphQLUrl

  GraphQLApiKey:
    Description: The API key used to invoke the SimpleTodoAPI GraphQL API
    Value: !GetAtt SimpleTodoAPIApiKey.ApiKey

  TodoTableName:
    Description: The name of the DynamoDB table backing the API
    Value: !Ref TodoTable
